// The WITNESS interface: talk with the world's steward, switch its autonomy, inspect its goals,
// review every act it (or the Creator) performed, read its memories, and see the life it tends.
// Everything shown comes from the engine; WITNESS's words are generated by its own reasoning code
// from real observations, never by this UI.

import { useCallback, useEffect, useRef, useState } from "react";
import { api, type DivineCommand, type LifeData, type Status, type WitnessMemory, type WitnessMessage, type WitnessState } from "../api";

type Sub = "talk" | "goals" | "acts" | "memory" | "life";

const KIND_LABEL: Record<string, string> = {
  instruction: "instruction", conversation: "heard", creation: "act", discovery: "noticed",
  lesson: "lesson", mistake: "mistake", goal: "goal",
};

export function WitnessPanel({ status, life, onLocate }: {
  status: Status | null; life: LifeData | null; onLocate: (xMetres: number, yMetres: number) => void;
}) {
  const [sub, setSub] = useState<Sub>("talk");
  const [w, setW] = useState<WitnessState | null>(null);
  const [msgs, setMsgs] = useState<WitnessMessage[]>([]);
  const [text, setText] = useState("");
  const [busy, setBusy] = useState(false);
  const [pending, setPending] = useState<string | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [acts, setActs] = useState<DivineCommand[]>([]);
  const [queued, setQueued] = useState<DivineCommand[]>([]);
  const [mems, setMems] = useState<WitnessMemory[]>([]);
  const lastId = useRef(0);
  const scroller = useRef<HTMLDivElement>(null);
  const tpd = status?.ticks_per_day ?? 24;

  const add = useCallback((m: WitnessMessage[]) => {
    if (!m.length) return;
    setMsgs((old) => {
      const seen = new Set(old.map((x) => x.id));
      const fresh = m.filter((x) => x.id === undefined || !seen.has(x.id));
      return [...old, ...fresh].slice(-300);
    });
    for (const x of m) if (x.id && x.id > lastId.current) lastId.current = x.id;
  }, []);

  // first open: load history, then let WITNESS introduce itself if it never has
  useEffect(() => {
    let alive = true;
    (async () => {
      try {
        const [st, hist] = await Promise.all([api.witness(), api.witnessMessages(0)]);
        if (!alive) return;
        setW(st);
        add(hist.messages);
        if (!st.introduced) add((await api.witnessIntroduce()).messages);
      } catch (e) {
        setErr(String(e));
      }
    })();
    return () => { alive = false; };
  }, [add, status?.world_id]);

  // WITNESS also speaks on its own (discoveries, emergencies): poll for new messages and state
  useEffect(() => {
    const t = setInterval(async () => {
      try {
        const [st, m] = await Promise.all([api.witness(), api.witnessMessages(lastId.current)]);
        setW(st);
        add(m.messages);
      } catch { /* server restarting; try again */ }
    }, 3000);
    return () => clearInterval(t);
  }, [add]);

  useEffect(() => {
    if (sub === "acts") api.commands().then((r) => { setActs(r.commands.slice().reverse()); setQueued(r.queued); }).catch(() => {});
    if (sub === "memory") api.witnessMemories().then((r) => setMems(r.memories.slice().reverse())).catch(() => {});
  }, [sub, msgs.length, status?.calendar.day_total]);

  useEffect(() => { scroller.current?.scrollTo({ top: 1e9 }); }, [msgs.length, sub, pending, busy]);

  const send = async (t: string) => {
    if (!t.trim() || busy) return;
    setBusy(true); setErr(null); setPending(t);
    setText("");
    const before = lastId.current;
    try {
      const r = await api.witnessSay(t);
      setW(r.witness);
      add((await api.witnessMessages(before)).messages); // the stored conversation, in order
    } catch (e) {
      setErr(String(e));
    } finally {
      setBusy(false);
      setPending(null);
    }
  };

  const autonomy = async (on: boolean) => {
    try { const r = await api.witnessAutonomy(on); setW(r.witness); add(r.messages); } catch (e) { setErr(String(e)); }
  };

  const day = (tick: number) => `day ${Math.floor(tick / tpd)}`;
  const state = !w ? "…" : w.acting_now ? "awake · acting on its own" : w.autonomy ? "awake · engine paused, so not acting"
    : "awake · acts only when asked";

  return (
    <div className="witness">
      <div className="wit-head">
        <div className="wit-sigil" aria-hidden>✦</div>
        <div>
          <div className="wit-name">WITNESS</div>
          <div className={`wit-state ${w?.acting_now ? "live" : ""}`}>{state}</div>
        </div>
        <label className="switch" title="When on, WITNESS observes, plans and acts each simulated day while the engine runs">
          <input type="checkbox" checked={!!w?.autonomy} onChange={(e) => autonomy(e.target.checked)} aria-label="Autonomy" />
          <span>Autonomy</span>
        </label>
      </div>
      <div className="subtabs">
        {(["talk", "goals", "acts", "memory", "life"] as Sub[]).map((k) => (
          <button key={k} className={sub === k ? "on" : ""} onClick={() => setSub(k)}>{k}</button>
        ))}
      </div>

      {sub === "talk" && (
        <>
          <div className="chat" ref={scroller}>
            {msgs.map((m, i) => (
              <div key={m.id ?? `o${i}`} className={`msg ${m.speaker}`}>
                <span className="who">{m.speaker === "witness" ? "WITNESS" : "CREATOR"}</span>
                <span className="when">{day(m.tick)}</span>
                <p>{m.text}</p>
              </div>
            ))}
            {pending && <div className="msg creator"><span className="who">CREATOR</span><p>{pending}</p></div>}
            {busy && <div className="msg witness thinking"><span className="who">WITNESS</span><p>…</p></div>}
          </div>
          {err && <div className="note err">{err}</div>}
          <form className="say" onSubmit={(e) => { e.preventDefault(); send(text); }}>
            <input value={text} onChange={(e) => setText(e.target.value)} placeholder="Speak to WITNESS…" aria-label="Message to WITNESS" maxLength={2000} />
            <button className="gold" disabled={busy || !text.trim()}>Send</button>
          </form>
          <div className="hints">
            {["What do you see?", "You decide. Create a civilization, but protect the environment.", "What have you learned?", "Create 20 deer"].map((h) => (
              <button key={h} className="chip" onClick={() => send(h)} disabled={busy}>{h}</button>
            ))}
          </div>
        </>
      )}

      {sub === "goals" && w && (
        <div className="wit-body">
          <h4>Instructions it follows</h4>
          <ul className="kv">
            <li>Protect the environment <b>{w.directives.protect_environment ? "yes" : "no"}</b></li>
            <li>Intervention <b>{w.directives.intervention}</b></li>
            <li>May create life <b>{w.directives.may_create_life ? "yes" : "no"}</b></li>
            <li>May create humans <b>{w.directives.may_create_humans ? "yes" : "no"}</b></li>
          </ul>
          <h4>Goals</h4>
          {w.goals.length === 0 ? <p className="dim">None yet.</p> : w.goals.map((g) => (
            <div key={g.id} className="goal"><b>{g.text}</b> <span className="dim">· {g.status} · stage {g.stage} · since {day(g.created_tick)}</span>
              {g.notes.slice(-2).map((n, i) => <div key={i} className="dim small">{n}</div>)}</div>
          ))}
          <h4>Acts awaiting verification</h4>
          {w.pending_verifications.length === 0 ? <p className="dim">None.</p> : w.pending_verifications.map((p) => (
            <div key={p.seq} className="small">#{p.seq} {p.kind.replace(/_/g, " ")} — checks on {day(p.check_tick)}</div>
          ))}
          <h4>What it has learned about its own acts</h4>
          {Object.keys(w.action_values).length === 0 ? <p className="dim">No outcomes measured yet.</p> : (
            <ul className="kv">{Object.entries(w.action_values).map(([k, v]) => (
              <li key={k}>{k.replace(/_/g, " ")} <b className={v.mean >= 0 ? "ok" : "bad"}>{v.mean >= 0 ? "+" : ""}{v.mean.toFixed(2)}</b> <span className="dim">({v.n} judged)</span></li>
            ))}</ul>
          )}
          <p className="dim small">WITNESS is a deterministic reasoning system, not a language model. It never ages; its identity and memories live in this world's database. It acts only while the engine process runs.</p>
        </div>
      )}

      {sub === "acts" && (
        <div className="wit-body">
          {queued.length > 0 && <><h4>Waiting for the next hour</h4>{queued.map((c) => <div key={`q${c.seq}`} className="act queued">#{c.seq} {c.kind.replace(/_/g, " ")} <span className="dim">by {c.issuer}</span></div>)}</>}
          <h4>Every recorded act</h4>
          <p className="dim small">These commands are the only way anything outside physics changed this world. Replaying them reproduces it exactly.</p>
          {acts.length === 0 ? <p className="dim">No acts yet.</p> : acts.map((c, i) => (
            <div key={`${c.seq}-${i}`} className={`act ${c.status}`}>
              <span className="dim">{day(c.tick)}</span> <b>{c.issuer === "witness" ? "WITNESS" : "Creator"}</b> {c.text}
              {c.status !== "applied" && <span className="bad"> — {c.status}{c.result?.error ? `: ${String(c.result.error)}` : ""}</span>}
              {c.reason && <div className="dim small">why: {c.reason}</div>}
            </div>
          ))}
        </div>
      )}

      {sub === "memory" && (
        <div className="wit-body">
          {mems.length === 0 ? <p className="dim">No memories yet.</p> : mems.map((m) => (
            <div key={m.id} className={`mem ${m.kind}`}><span className="tag">{KIND_LABEL[m.kind] ?? m.kind}</span>
              <span className="dim">{day(m.tick)}</span> {m.text}</div>
          ))}
        </div>
      )}

      {sub === "life" && (
        <div className="wit-body">
          {!life?.present || !life.summary ? <p className="dim">No creature lives in this world yet. Ask WITNESS, or tell it to decide.</p> : (
            <>
              <ul className="kv">
                {Object.entries(life.summary.animals).sort((a, b) => b[1] - a[1]).map(([k, n]) => <li key={k}>{k}{k === "insect" ? " colonies" : ""} <b>{n}</b></li>)}
                <li>humans <b>{life.summary.humans}</b></li>
                <li>families <b>{life.summary.families}</b></li>
                <li>shelters <b>{life.summary.shelters}</b>{life.summary.shelters_in_progress ? <span className="dim"> (+{life.summary.shelters_in_progress} building)</span> : null}</li>
                <li>births · deaths <b>{Object.values(life.summary.births).reduce((a, b) => a + b, 0)} · {Object.values(life.summary.deaths).reduce((a, d) => a + Object.values(d).reduce((x, y) => x + y, 0), 0)}</b></li>
              </ul>
              {life.summary.humans_adult > 0 && <><h4>Skills (adults, learned by practice and teaching)</h4>
                <ul className="kv">{Object.entries(life.summary.mean_skills).map(([k, v]) => <li key={k}>{k} <b>{v.toFixed(2)}</b></li>)}</ul></>}
              {life.summary.births_capped > 0 && <p className="note small">Engine limit reached: {life.summary.births_capped} animal births were not simulated (limit {life.summary.max_animals.toLocaleString()} animals).</p>}
              <h4>People</h4>
              {(life.agents?.humans ?? []).slice(0, 40).map((h) => (
                <button key={h[0]} className="person" onClick={() => onLocate(h[2], h[3])} title="Fly the 3D view to them">
                  <b>{h[1]}</b> <span className="dim">{h[5].toFixed(0)} y · {h[4]}</span>
                </button>
              ))}
              <p className="dim small">{life.summary.insects_note}. Life model v{life.summary.life_version}.</p>
            </>
          )}
        </div>
      )}
    </div>
  );
}
